def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    sep_colors = [grid[r][0] for r in sep_rows] + [grid[0][c] for c in sep_cols]
    sep_color = max(set(sep_colors), key=sep_colors.count) if sep_colors else None

    row_ranges = []
    start = 0
    for r in sep_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))

    col_ranges = []
    start = 0
    for c in sep_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    from collections import Counter
    interior = [
        grid[r][c]
        for r0, r1 in row_ranges
        for c0, c1 in col_ranges
        for r in range(r0, r1)
        for c in range(c0, c1)
    ]
    counts = Counter(x for x in interior if x != sep_color)
    background = counts.most_common(1)[0][0]

    panels = [(r0, r1, c0, c1)
              for r0, r1 in row_ranges
              for c0, c1 in col_ranges]
    source = max(
        panels,
        key=lambda p: sum(grid[r][c] != background
                          for r in range(p[0], p[1])
                          for c in range(p[2], p[3]))
    )
    sr0, sr1, sc0, sc1 = source
    pattern = [row[sc0:sc1] for row in grid[sr0:sr1]]

    out = [row[:] for row in grid]
    for r0, r1, c0, c1 in panels:
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = pattern[r - r0][c - c0]
    return out
